import React, { useState } from "react";
import { Button } from "@mui/material";
import { Dropdown } from "react-bootstrap";
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import DialogContentText from '@mui/material/DialogContentText';
import "../resources/Midcontent.css";
import SecondLevelLetter from "../resources/SecondLevelLetter.json";
import i_image from "../Img/i_image.png";
import parse from 'html-react-parser';
import Swal from "sweetalert2";
import hintLetter from "../Img/letterImg/hintLetter.png";
import "../css/common.css";

const MidLevelOneDisplayLetter = ({ instruction, detailsOfSelLetter }) => {

  const [open, setOpen] = useState(false);
  const [hintText, setHintText] = useState("");
  const [hintTitle, setHintTitle] = useState("Instructions");
  var [mainArr, setmainArr] = useState(SecondLevelLetter);
  var [idxLetter, setIdxLetter] = useState(0);
  const [enableHint, setEnableHint] = useState(0);
  const [hintInstr, setHintInstr] = useState({});
  const [openInstrun, setOpenInstrun] = useState(false);
         
  const handleClose = () => {
      setHintText("");
      setOpen(false)
  };
    
  const toggleDialog = () => {
    setOpenInstrun(true);
  };
  
  const handleCloseInstrun = () => {
      setOpenInstrun(false);
  }; 
  
  const prevLetter = () => {
      if(idxLetter > 0){
          var inputs = document.getElementsByTagName('select');
          for(var i=0; i<inputs.length; i++ ){
              inputs[i].selectedIndex = 0;
              inputs[i].style.borderColor = "black";
          }      
          
          // ==================== //
          setIdxLetter(idxLetter-1); 
          setEnableHint(0) 
      }
  };
  
  const nextLetter = () => {
      var lengthLetter = mainArr.length;
      
      if(idxLetter < lengthLetter-1) {
          var inputs = document.getElementsByTagName('select');
          for(var i=0; i<inputs.length; i++ ){
              inputs[i].selectedIndex = 0;
              inputs[i].style.borderColor = "black";
          }  
          
          // ==================== //    
          setIdxLetter(idxLetter+1); 
          setEnableHint(0) 
      }
  }; 
  
  const checkLetter = () => {
      setEnableHint(1);
      const letterDetails = mainArr[idxLetter];     
      const listKeys = Object.keys(letterDetails);
      var objHint = {};
            
      listKeys.map((word, index) => {
            if( Array.isArray(letterDetails[word])){
                if(letterDetails[word].length !== 0){
                    letterDetails[word].map((details, idxDet) => {
                    
                        // Details of the target elements.........
                        var idOfElement = word + "_" + idxDet;  // generate Id string
                        var targetElement = document.getElementById(idOfElement);  // Get element by Id
                        
                        if(details.options !== "" ){
                            if(details.correct === targetElement.selectedOptions[0].innerHTML){
                                document.getElementById(idOfElement).style.borderColor = "green";
                                objHint[idOfElement] = details.feedbackCorrent;
                            }else{
                                document.getElementById(idOfElement).style.borderColor = "red";
                                objHint[idOfElement] = details.feedbackIncorrent;
                            }
                        }
                        
                    });                    
                }
            }
      })
           
      setHintInstr(objHint);
  };
  
  const getFeedback = (e) => {
      var idOfElement = e.target.id;
      const myArray = idOfElement.split("_");
      const varId = myArray[0]+"_"+myArray[2];
      
      setHintText(hintInstr[varId]);
      //setOpen(true);
      
      Swal.fire({  
          //icon: 'error',  
	  title: "Hint",  
	  text: 'Please try again !',
	  //html: '<span>' + hintInstr[varId] + '</span>' + '<br/>' + "<img src='" + hintLetter + "' style='width:85%; height:92%;'>",
	  html: '<span>' + hintInstr[varId] + '</span>',           
          //customClass: 'swalCss',  
	  footer: ''  
      });      
      
  };      
  
  return (
      
      <div className="row-md-auto" style={{ height: "100%", width:"100%", borderRadius: "20px", background: "#F2FBFF"}} >
      <div className="row-md-auto" style={{ height: "100%", width:"100%", borderRadius: "20px", }}>      
      
          {/* =============================== Start of Header ================================= */}
          <div className="row-md-auto d-flex " style={{height: "8%"}} >
              <div className="" style={{width: "20%", display: "flex", textAlign:"center"}} >
                  <div style={{width: "40%"}} ></div>
                  <h6 className="" style={{ backgroundColor: "rgb(245, 211, 139)", height:"70%", borderRadius:"0 0 10px 10px", width: "70%", paddingTop: "2%", marginLeft: "1vh", color: "#220730" }} >
                      <strong style={{fontSize:"1.2rem"}}>Level 1 </strong>
                  </h6>
              </div>
              
              <div className="col text-center" >
                {/*  <h5 style={{ paddingTop: "10px", color: "white" }}>
                      <strong> {mainArr === null ? <></> : <> {mainArr[idxLetter].lettername} </>} </strong>
                  </h5>
                */}
              </div>
                  
              <div className="col-md-auto" style= {{width: "31%", display:"flex", margin: "auto", textAlign: "center", alignContent: "center", justifyContent:"center"}}>
          
                  <Button style={{ marginRight:"2vh", height:"100%", color:"white" }}       
                      onClick={toggleDialog} variant="contained" > Instructions 
                  </Button>            
          
                  <Dropdown className="d-flex justify-content-end" style={{height:"90%"}}>
                      <Dropdown.Toggle style={{backgroundColor:"#1976d2", fontSize:"0.95rem"}}
                         id="dropdown-basic"
                      >  SELECT LEVEL </Dropdown.Toggle>

                     <Dropdown.Menu style={{ background: "#F7F1FC" }}>
                          <Dropdown.Item href="#/launchpage/l1-letter" style={{ color: "#350B5B" }} >
                              Level 1
                          </Dropdown.Item>
                
                          <Dropdown.Item href="#/launchpage/l2-select-letter" style={{ color: "#350B5B" }} > 
                              Level 2
                          </Dropdown.Item>
                
                          {/* <Dropdown.Item href="#/launchpage/select-letter" style={{ color: "#350B5B" }} >
                               Level 3
                          </Dropdown.Item> */}    
                     </Dropdown.Menu> 
                  </Dropdown>
              </div>
          </div>
          {/* =============================== End of Header ================================= */}
        
        
        <div
          className="row"
          style={{
            // border: "1px solid #A7A8AB",
            height: "92%",
            width: "99.9%",
            marginLeft: "0.1%",
            marginRight: "0.1%",
            // backgroundColor: "#E4CDFF",
            paddingLeft: "1%",
            paddingTop: "1%",
            fontSize: "2.2vh",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            background: "#FFFFFF",
            //backgroundColor:"#FFFFFF 0% 0% no-repeat padding-box",
          }}
        >
        
        {mainArr === null ? <>
            <h1>Content Not available .... !! </h1>
        </> : 
        
          <div className="row-md-auto overflow-auto" style={{fontSize: "2.2vh", height:"90%"}}>
            <div className="row d-flex justify-content-center"> {mainArr[idxLetter].titleOfLetter} </div> 

            {/* ################ Subject == Start : Display the contents of Date ################### */} 

            <div className="row-md-auto wrap">  
                  {Object.keys(mainArr[idxLetter]).map((keyName, index) =>
                      <>
                      {Array.isArray((mainArr[idxLetter])[keyName]) ? 
                          ((mainArr[idxLetter])[keyName]).length !== 0 ?                      
                             <> 
                                 <div id={keyName} style={{maxWidth:"100%", display: "inline", flexWrap: "wrap", margin: "0"}}>
                                     { ((mainArr[idxLetter])[keyName]).map((slotitem, index1) =>
                                        <>
                                             <div id={keyName+"_"+index1+"_"+"2"} style={{display:"flex", marginRight:"0.5%", marginBottom:"0.4%"}}>
                                                 {slotitem.options === "" ? <>{parse(slotitem.sentence)}</> :
                                                 <>
                                                 
                                                     {keyName === "subject" ? <div >{slotitem.sentence}</div> : <></>}
                                                 
                                                     <select
				                         size="sm"
				                         aria-label="Default select example"
				                         style={{ borderWidth: "2px", fontSize: "2.2vh",
				                             borderRadius: "5px", paddingLeft: "1%",
				                             borderColor: "black",
				                         }}
				                         id={keyName+"_"+index1}                                         
                                                     >
                                                         <option disabled hidden selected></option>
                                                         {slotitem.options.map((word, index) => (
                                                             <option id={word} value={word} className="col">{word}</option>
                                                         ))}
                                                         
                                                     </select>
                                                     
                                                     {enableHint === 1 ?  
                                                         <img id={keyName+"_"+"hint_"+index1}
                                                             src={i_image}
                                                             style={{ marginLeft: "1vh",height:"3.5vh",width:"3.5vh" }}
                                                             onClick={getFeedback} alt="i"
                                                         >
                                                         </img>   
                                                         : <></>
                                                     }
                                               </>}
                                          </div>                                              
                                     </>)}
                                 </div>
                                 <p></p>       
                             </>
                              
                          : <></>
                          : <></>
                      }
                  
                      </>                  
                  )}
            </div>
                                    
            {/* ################ Subject == End : Display the contents ################### */}
	    
	    <Dialog
		open={open}
		onClose={handleClose}
		aria-labelledby="alert-dialog-title"
		aria-describedby="alert-dialog-description"
		PaperProps={{ sx: { width: "30%", maxHeight: 300 }}}
	    >
		<DialogTitle style={{minWidth:"50%"}} id="alert-dialog-title"> {hintTitle} </DialogTitle>
		<DialogContent>
		  <DialogContentText id="alert-dialog-description"> {hintText} </DialogContentText>
		</DialogContent>
		<DialogActions>
		  <Button class="btn btn-danger" onClick={handleClose}>Cancel</Button>
		  <Button class="btn btn-primary" onClick={handleClose} autoFocus> Ok </Button>
		</DialogActions>
	    </Dialog>        

	    <Dialog
		open={openInstrun}
		onClose={handleCloseInstrun}
		aria-labelledby="alert-dialog-title"
		aria-describedby="alert-dialog-description"
		PaperProps={{ sx: {
		               width: "80%",
		               maxHeight: "56%",
		               }
		           }}
	      >
		<DialogTitle style={{minWidth:"80%"}} id="alert-dialog-title">
		  {hintTitle}
		</DialogTitle>
		<DialogContent>
		  <DialogContentText id="alert-dialog-description">
		    <div style={{ maxHeight: "50vh", padding: "2%" }}>
		        <div>
		            <ul>
		                <li>The letter displayed, has empty input boxes to be filled.</li>
		                <li>For each empty input box select an appropriate option from the dropdown. </li>
		                <li>Click on "Check" to verify. </li>
		                <li>For incorrect answers click on the hint icon.</li>
		                <li>Based on the hints given, try to choose the correct option.</li>
		                <li>Click on "Check" to verify again.</li>
		                <li>Click on "Next" to attempt the next letter.</li>
		                <li>Click on "Previous" to go to the previous letter.</li>
		                <li>Click on "Select Level" to attempt "Level 1" or "Level 2".</li>
		            </ul>
		        </div>
		    </div>
		  </DialogContentText>
		</DialogContent>
		<DialogActions>
		  <Button class="btn btn-danger" onClick={handleCloseInstrun}>Cancel</Button>
		  <Button class="btn btn-primary" onClick={handleCloseInstrun} autoFocus>
		    Ok
		  </Button>
		</DialogActions>
	    </Dialog>
          </div> 
        }
           <br/>
              <div style={{maxWidth:"100%", fontSize:"80%", justifyContent:"center", textAlign: "center", margin: "0"}}>                
                <Button style={{minWidth:"10%", fontSize:"100%", margin:"1%"}} onClick={prevLetter} variant="contained"> Previous </Button>   
                <Button style={{minWidth:"10%", fontSize:"100%", margin:"1%"}} onClick={checkLetter} variant="contained"> Check </Button> 
                <Button style={{minWidth:"10%", fontSize:"100%", margin:"1%"}} onClick={nextLetter} variant="contained"> Next </Button>       
              </div>         
        </div>                 
        </div>        
      </div>
  );
};

export default MidLevelOneDisplayLetter;
